def temp_learning(**kw) -> Learning:
    "A `Learning` on a new vault in a temporary folder, with the offline hashing encoder."
    import tempfile
    return Learning(Vault(str(Path(tempfile.mkdtemp())/'vault.db'), offline=True), **kw)
